try{$user=(new LegacyAuthAdapter())->current();$permission=new PermissionService();$permission->require($user,'material_center.supplier.manage');$service=new SupplierService();if($_SERVER['REQUEST_METHOD']==='GET'&&in_array(($_GET['action']??''),['download_document','preview_document'],true)){$file=$service->document((int)($_GET['id']??0));$preview=($_GET['action']??'')==='preview_document'&&in_array($file['mime_type'],['application/pdf','image/png','image/jpeg','image/webp'],true);while(ob_get_level())ob_end_clean();header('Content-Type: '.$file['mime_type']);header('Content-Disposition: '.($preview?'inline':'attachment').'; filename="'.rawurlencode($file['file_name']).'"');header('Content-Length: '.$file['file_size']);header('X-Content-Type-Options: nosniff');header("Content-Security-Policy: default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'");readfile($file['file_path']);exit;}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf((string)($_POST['csrf_token']??'')))throw new RuntimeException('安全令牌已过期。',419);$action=(string)($_POST['action']??'save_supplier');$data=[];if($action==='save_supplier'){$id=$service->saveSupplier($_POST,$user->id);$message='供应商已保存';$data=['id'=>$id];}elseif($action==='upload_document'){$id=$service->uploadDocument($_FILES['file']??[],$_POST,$user->id);$message='供应商附件已上传';$data=['id'=>$id];}elseif($action==='save_price'){$permission->require($user,'material_center.purchase_price.edit');$payload=$_POST;if(isset($_POST['tiers_json']))$payload['tiers']=json_decode((string)$_POST['tiers_json'],true)?:[];$id=$service->savePrice($payload,$user->id);$message='价格已提交审批';$data=['id'=>$id];}elseif($action==='upload_prices'){$permission->require($user,'material_center.purchase_price.edit');$data=(new ImportService())->uploadPrices($_FILES['file']??[],$user->id);$message='价格文件预检完成';}elseif($action==='execute_prices'){$permission->require($user,'material_center.purchase_price.edit');$data=(new ImportService())->executePrices((string)($